/**
 * Comark hands every component a bag of props parsed out of Markdown.
 *
 * Two things need normalising before those props can reach a typed React
 * component:
 *
 * 1. Scalars arrive as strings. `{value=0.82}` and `ticks: 24` both become
 *    `"0.82"` and `"24"` — Markdown attributes have no number type. Arrays and
 *    objects are the exception: Comark JSON-encodes them on the way in and
 *    parses them back out, so `rows:` and `data:` arrive as real values.
 * 2. Keys may carry a leading `:`. Comark keeps Vue-style binding keys
 *    (`{legend}` → `:legend`, `{:data='[1,2]'}` → `:data`) intact for the
 *    renderer to resolve.
 *
 * `coerceProps` undoes both, so a component can keep its normal typed API and
 * stay usable from TSX as well as from Markdown.
 */

export type NumericProps = readonly string[]

function toNumber(value: unknown): unknown {
  if (typeof value !== "string") return value
  const trimmed = value.trim()
  if (trimmed === "") return value
  const parsed = Number(trimmed)
  return Number.isFinite(parsed) ? parsed : value
}

/**
 * `"true"` / `"false"` only. Anything else is left alone, so a genuine string
 * prop is never clobbered — that matters for props like the activity graph's
 * `caption?: string | false`.
 */
function toBoolean(value: unknown): unknown {
  if (value === "true") return true
  if (value === "false") return false
  return value
}

export function coerceProps<T extends Record<string, unknown>>(
  props: Record<string, unknown>,
  numeric: NumericProps = []
): T {
  const out: Record<string, unknown> = {}

  for (const [rawKey, rawValue] of Object.entries(props)) {
    if (rawKey.startsWith("$")) continue

    const unprefixed = rawKey.startsWith(":") ? rawKey.slice(1) : rawKey
    const key = unprefixed === "class" ? "className" : unprefixed
    const value = toBoolean(rawValue)

    out[key] = numeric.includes(key) ? toNumber(value) : value
  }

  return out as T
}

"use client"

import type { ComponentType } from "react"

import { Graph, GraphBody } from "@/registry/default/graph-frame/graph-frame"
import type { GraphAdapter } from "@/registry/default/graph-comark/adapters"
import { coerceProps } from "@/registry/default/graph-comark/coerce"

/**
 * Shown while a block's props are still incomplete.
 *
 * Comark auto-closes a dangling `::graph-table`, but a component's props live
 * in a `---` fence that the parser only accepts once the closing fence
 * arrives. For a few frames the tag exists with no props, and `rows.map(...)`
 * would throw. Reserving the frame keeps the layout stable.
 */
function PendingGraph({ title }: { title?: string }) {
  return (
    <Graph title={title}>
      <GraphBody className="flex items-center justify-center py-14">
        <span className="font-mono text-sm text-graph-frame select-none">
          · · ·
        </span>
      </GraphBody>
    </Graph>
  )
}

function isPresent(value: unknown): boolean {
  if (value == null) return false
  if (Array.isArray(value)) return value.length > 0
  if (typeof value === "string") return value.trim() !== ""
  return true
}

/**
 * A key that changes when a figure's data changes, so the graph remounts.
 *
 * The graphs animate with `whileInView` and `viewport={{ once: true }}`. When
 * Markdown is streaming, rows arrive one at a time — children mounted after
 * the parent's once-only animation has fired sit at `opacity: 0`. Remounting
 * on a data change lets the animation run again over the full set.
 *
 * On a static page the props never change, so this is one string per figure.
 * `children` is skipped: React elements are cyclic, and a layout block's
 * identity is its own props.
 */
function propsKey(props: Record<string, unknown>): string | undefined {
  try {
    const parts: string[] = []
    for (const [key, value] of Object.entries(props)) {
      if (key === "children") continue
      parts.push(
        `${key}=${typeof value === "object" && value !== null ? JSON.stringify(value) : String(value)}`
      )
    }
    return parts.join("|")
  } catch {
    return undefined
  }
}

export function fromMarkdown<P extends Record<string, unknown>>(
  Component: ComponentType<P>,
  { numeric = [], required = [] }: GraphAdapter = {}
) {
  function MarkdownGraph(raw: Record<string, unknown>) {
    const props = coerceProps<P>(raw, numeric)

    if (!required.every((key) => isPresent(props[key]))) {
      return <PendingGraph title={props.title as string | undefined} />
    }

    return <Component key={propsKey(props)} {...props} />
  }

  MarkdownGraph.displayName = `FromMarkdown(${
    Component.displayName ?? Component.name ?? "Graph"
  })`

  return MarkdownGraph as ComponentType<Record<string, unknown>>
}

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"

type GraphRowProps = {
  cols?: number
  className?: string
  children?: ReactNode
}

/**
 * Nested Comark blocks. `::row{cols=2}` puts two figures on one line.
 * Collapses to a single column on small screens.
 */
function GraphRow({ cols = 2, className, children }: GraphRowProps) {
  return (
    <div
      className={cn(
        "grid gap-4",
        cols <= 1 && "grid-cols-1",
        cols === 2 && "grid-cols-1 sm:grid-cols-2",
        cols >= 3 && "grid-cols-1 sm:grid-cols-2 lg:grid-cols-3",
        className
      )}
    >
      {children}
    </div>
  )
}

export { GraphRow }
export type { GraphRowProps }
